test_m3 = '''"""Tests for milestone m3: @cachedmethod raises DeprecationWarning when key returns None."""

import warnings


def test_cachedmethod_none_key_raises_deprecation_warning():
    """Test that @cachedmethod raises DeprecationWarning when key function returns None."""
    import cachetools
    from cachetools import cachedmethod

    class MyClass:
        def __init__(self):
            self._cache = {}

        @cachedmethod(lambda self: self._cache)
        def get_value(self, flag):
            if not flag:
                return None  # key function will return None via methodkey
            return "computed"

    obj = MyClass()

    # When the key resolves to something that maps to None caching behavior,
    # a DeprecationWarning should be raised
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        result = obj.get_value(False)
        # Check that at least one DeprecationWarning was raised
        deprecation_warnings = [x for x in w if issubclass(x.category, DeprecationWarning)]
        assert len(deprecation_warnings) >= 1, f"Expected DeprecationWarning but got: {[str(x.message) for x in w]}"


def test_cachedmethod_valid_key_no_warning():
    """Test that @cachedmethod does not raise warning for valid keys."""
    import cachetools
    from cachetools import cachedmethod

    class MyClass:
        def __init__(self):
            self._cache = {}

        @cachedmethod(lambda self: self._cache)
        def compute(self, x):
            return x * 2

    obj = MyClass()

    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        result = obj.compute(5)
        assert result == 10
        deprecation_warnings = [x for x in w if issubclass(x.category, DeprecationWarning)]
        assert len(deprecation_warnings) == 0, f"Unexpected DeprecationWarning: {[str(x.message) for x in w]}"


def test_cachedmethod_none_key_still_returns_result():
    """Test that even with DeprecationWarning, the function still returns its result."""
    import cachetools
    from cachetools import cachedmethod

    class MyClass:
        def __init__(self):
            self._cache = {}

        @cachedmethod(lambda self: self._cache)
        def fetch(self, condition):
            if condition:
                return "data"
            return None

    obj = MyClass()

    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        result = obj.fetch(True)
        assert result == "data"
        deprecation_warnings = [x for x in w if issubclass(x.category, DeprecationWarning)]
        assert len(deprecation_warnings) >= 1
'''

